customCss:
/* ZeroScroll Core CSS Guard */
a[href='/'], a[href^='/explore'], a[href^='/reels'], a[aria-label='Home'], a[aria-label='Search'], a[aria-label='Explore'], a[aria-label='Reels'], section[aria-label='Stories'], div[aria-label*='Stories'], div[data-testid='story-tray'] { display: none !important; visibility: hidden !important; pointer-events: none !important; opacity: 0 !important; }
div[role='banner'], div:has(> a[href*='play.google.com']), div:has(> a[href*='apps.apple.com']) { display: none !important; visibility: hidden !important; }
